package com.hbm.machine.oreslopper;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
/** Exact original seven-long by three-wide body with source eight detailed collision boxes. */
public final class OreSlopperBlock extends DummyableBlock {
 private static final double[][] BOXES={{-3.5,0,-1.5,3.5,1,1.5},{.5,1,-1.5,3.5,3.25,1.5},{-2.25,1,-1.5,.25,3.25,-.75},{-2.25,1,.75,.25,3.25,1.5},{-2.25,1,-1.5,-2,3.25,1.5},{0,1,-1.5,.25,3.25,1.5},{-2,1,-.75,0,2,.75},{-3.25,1,-1,-2.25,3,1}};
 public OreSlopperBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion().dynamicShape());}
 @Override protected MapCodec<? extends DummyableBlock> codec(){return MapCodec.unit(this);}@Override public int[] dimensions(){return new int[]{3,0,3,3,1,1};}@Override public int offset(){return 3;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);if(level.isClientSide)return;var facing=placementFacing(state);var core=pos.relative(facing,-offset());for(var port:OreSlopperBlockEntity.physicalPorts(core,facing))setPort(level,port,true);}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new OreSlopperBlockEntity(pos,state):isPort(state)?new OreSlopperPort(pos,state):null;}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,OreSlopperContent.ENTITY.get(),OreSlopperBlockEntity::tick):null;}
 @Override protected VoxelShape getShape(BlockState state,BlockGetter world,BlockPos pos,CollisionContext context){var core=findCore(world,pos);if(core==null)return Shapes.empty();var rotation=facing(world.getBlockState(core)).getClockWise();VoxelShape shape=Shapes.empty();for(var b:BOXES){AABB box=switch(rotation){case EAST->new AABB(-b[5],b[1],b[0],-b[2],b[4],b[3]);case SOUTH->new AABB(-b[3],b[1],-b[5],-b[0],b[4],-b[2]);case WEST->new AABB(b[2],b[1],-b[3],b[5],b[4],-b[0]);default->new AABB(b[0],b[1],b[2],b[3],b[4],b[5]);};box=box.move(core.getX()+.5-pos.getX(),core.getY()-pos.getY(),core.getZ()+.5-pos.getZ());if(box.intersects(0,0,0,1,1,1))shape=Shapes.or(shape,Shapes.create(box.intersect(new AABB(0,0,0,1,1,1))));}return shape;}
 @Override protected VoxelShape getCollisionShape(BlockState state,BlockGetter world,BlockPos pos,CollisionContext context){return getShape(state,world,pos,context);}
}
